def test_mixed_mask():
    got = solution.dropout([2.0, 1.0, 0.5, 4.0], 0.3, [True, False, True, True])
    assert len(got) == 4
    assert abs(got[0] - 2.857142857142857) < 1e-9
    assert got[1] == 0.0
    assert abs(got[2] - 0.7142857142857143) < 1e-9
    assert abs(got[3] - 5.714285714285714) < 1e-9

def test_all_dropped():
    assert solution.dropout([1.0, 2.0], 0.5, [False, False]) == [0.0, 0.0]

def test_p_zero_identity():
    assert solution.dropout([1.5, 2.5], 0.0, [True, True]) == [1.5, 2.5]

def test_scales_survivors():
    assert abs(solution.dropout([2.0], 0.5, [True])[0] - 4.0) < 1e-12

def test_bad_p_raises():
    for p in (-0.1, 1.0, 1.5):
        try:
            solution.dropout([1.0], p, [True])
        except ValueError:
            continue
        raise AssertionError("expected ValueError for p=%r" % (p,))

def test_bad_mask_raises():
    try:
        solution.dropout([1.0, 2.0], 0.2, [True])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_no_mutation():
    values, mask = [2.0, 1.0], [True, False]
    before = values[:]
    solution.dropout(values, 0.25, mask)
    assert values == before and mask == [True, False]
